package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGradeService;
import net.officefloor.hq.app.person.PersonHold;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The figures a sheet rolls up to: each person's claimed and due-total, and the sheet's totals. A
 *  change made through {@link #track} is followed in the audit by a line for each person whose
 *  figures it moved, then one for the sheet's totals when they moved. */
@Service
public class RollupService {

    /** Written for a due-total that has no rate to work from. */
    private static final String NO_RATE = "n/a";

    private static final BigDecimal NONE = BigDecimal.ZERO.setScale(2);

    /** A person's figures; due is null when it has no rate to work from. */
    private record Figures(String name, BigDecimal claimed, BigDecimal due) {
        boolean sameAs(Figures other) {
            return other != null && claimed.compareTo(other.claimed) == 0 && Objects.equals(due, other.due);
        }
    }

    /** The sheet's figures: each person's, by id in the order they were added, and the totals. */
    private record Rollup(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final RateService rates;
    private final PersonGradeService grades;
    private final PersonService personService;
    private final SheetService sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, ClaimService claimService,
            RateService rates, PersonGradeService grades, PersonService personService, SheetService sheets,
            Audit audit) {
        this.people = people;
        this.claims = claims;
        this.claimService = claimService;
        this.rates = rates;
        this.grades = grades;
        this.personService = personService;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** Make a change to the sheet, then record in the audit the figures it moved. The sheet is held
     *  locked throughout, so a change made at the same moment waits and the figures are its own. */
    @Transactional
    public <T> T track(String sheetId, String user, Supplier<T> change) {
        sheets.lock(sheetId);
        Rollup before = rollup(sheetId);
        T result = change.get();
        Rollup after = rollup(sheetId);
        after.people().forEach((id, figures) -> {
            if (!figures.sameAs(before.people().get(id))) {
                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
                        + " claimed=" + figures.claimed().toPlainString() + " due-total=" + text(figures.due()));
            }
        });
        if (after.claimedTotal().compareTo(before.claimedTotal()) != 0
                || after.dueTotal().compareTo(before.dueTotal()) != 0) {
            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user
                    + " claimed-total=" + after.claimedTotal().toPlainString()
                    + " due-total=" + after.dueTotal().toPlainString());
        }
        return result;
    }

    private Rollup rollup(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Person> sheetPeople = people.findBySheetIdOrderByIdAsc(sheetId);
        Map<Long, List<PersonHold>> holds = personService.holds(sheetId);
        Map<Long, List<Claim>> counted = claims.findBySheetIdOrderByListedDesc(sheetId).stream()
                .filter(claim -> claim.countsLive(holds.getOrDefault(claim.getPersonId(), List.of())))
                .collect(Collectors.groupingBy(Claim::getPersonId));
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = NONE;
        BigDecimal dueTotal = NONE;
        for (Person person : sheetPeople) {
            Figures f = figuresOf(sheetId, today, person, counted.getOrDefault(person.getId(), List.of()));
            figures.put(person.getId(), f);
            claimedTotal = claimedTotal.add(f.claimed());
            if (f.due() != null) {
                dueTotal = dueTotal.add(f.due());
            }
        }
        return new Rollup(figures, claimedTotal, dueTotal);
    }

    /** A person's figures from their claims that count: the sum of their amounts, and the sum of the
     *  figures they show, or none when the grade in force on the sheet's today has no rate in force
     *  then and no claim of theirs shows a figure. */
    private Figures figuresOf(String sheetId, LocalDate today, Person person, List<Claim> counted) {
        BigDecimal claimed = NONE;
        BigDecimal due = NONE;
        boolean anyFigure = false;
        for (Claim claim : counted) {
            claimed = claimed.add(claim.getAmount());
            BigDecimal figure = claimService.dueOf(sheetId, person, claim);
            if (figure != null) {
                due = due.add(figure);
            }
            anyFigure |= figure != null;
        }
        boolean hasRate = rates.rateOn(sheetId, grades.gradeOn(person.getId(), today), today).isPresent();
        return new Figures(person.getName(), claimed, hasRate || anyFigure ? due : null);
    }

    private static String text(BigDecimal due) {
        return due == null ? NO_RATE : due.toPlainString();
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/settings")
public class SettingController {

    /** A user name's role as the screen shows it: clerk or steward. */
    public record RoleView(String user, String role) {
        static RoleView of(SheetRole role) {
            return new RoleView(role.getUser(), role.getRole().label());
        }
    }

    /** The sheet's settings: the roles assigned, the clerk limit (two decimals; null for none) and
     *  the floor (two decimals), the terms (whole days), the late percent (two decimals) and the policy
     *  date (blank for the sheet's today) and the period numbering from (blank for off), and the grades'
     *  own terms by grade (a grade not listed takes the sheet's terms). */
    public record SettingsView(List<RoleView> roles, String clerkLimit, String floor, int terms, String latePct,
            String policyDate, String periodNumberingFrom, Map<String, Integer> gradeTerms) {
    }

    /** A role for a user name: clerk or steward. */
    public record RoleRequest(@NotBlank @Size(max = 200) String user, @NotBlank String role) {
    }

    /** A clerk limit of 0.00 or more with up to two decimals; null removes the limit. */
    public record ClerkLimitRequest(@DecimalMin("0.00") @Digits(integer = 10, fraction = 2) BigDecimal value) {
    }

    /** A floor of 0.00 or more with up to two decimals. */
    public record FloorRequest(@NotNull @DecimalMin("0.00") @Digits(integer = 10, fraction = 2) BigDecimal value) {
    }

    /** Terms of 0 or more whole days. */
    public record TermsRequest(@NotNull @Min(0) @Max(36500) Integer value) {
    }

    /** A late percent of 0.00 or more with up to two decimals. */
    public record LatePctRequest(@NotNull @DecimalMin("0.00") @Digits(integer = 10, fraction = 2) BigDecimal value) {
    }

    /** A policy date; null leaves it blank (the sheet's today). */
    public record PolicyDateRequest(LocalDate value) {
    }

    /** A period numbering from date; null leaves it blank (off). */
    public record PeriodNumberingFromRequest(LocalDate value) {
    }

    private final SettingService service;
    private final RollupService rollups;

    public SettingController(SettingService service, RollupService rollups) {
        this.service = service;
        this.rollups = rollups;
    }

    /** The sheet's settings. */
    @GetMapping
    public SettingsView get(@PathVariable @NotBlank @Size(max = 200) String sheetId) {
        String sheet = sheetId.trim();
        return view(sheet);
    }

    /** Assign a user name a role; a role other than clerk or steward is refused. */
    @PutMapping("/roles")
    public RoleView setRole(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated RoleRequest request) {
        Role role = Role.of(request.role().trim())
                .orElseThrow(() -> new IllegalArgumentException("No role " + request.role()));
        return RoleView.of(service.setRole(sheetId.trim(), SignedInUser.decode(user), request.user().trim(), role));
    }

    /** Change the sheet's clerk limit. */
    @PutMapping("/clerk-limit")
    public SettingsView setClerkLimit(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated ClerkLimitRequest request) {
        String sheet = sheetId.trim();
        service.setClerkLimit(sheet, SignedInUser.decode(user), request.value());
        return view(sheet);
    }

    /** Change the sheet's floor; the figures it moves are followed in the audit. */
    @PutMapping("/floor")
    public SettingsView setFloor(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated FloorRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        rollups.track(sheet, by, () -> service.setFloor(sheet, by, request.value()));
        return view(sheet);
    }

    /** Change the sheet's terms; the late charges it moves are followed in the audit. */
    @PutMapping("/terms")
    public SettingsView setTerms(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated TermsRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        rollups.track(sheet, by, () -> service.setTerms(sheet, by, request.value()));
        return view(sheet);
    }

    /** Set a grade's (A, B or C) own terms; they fix the due-by of the grade's claims added from now on. */
    @PutMapping("/terms/{grade}")
    public SettingsView setGradeTerms(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated TermsRequest request) {
        String sheet = sheetId.trim();
        service.setGradeTerms(sheet, SignedInUser.decode(user), grade, request.value());
        return view(sheet);
    }

    /** Change the sheet's late percent; the figures it moves are followed in the audit. */
    @PutMapping("/late-pct")
    public SettingsView setLatePct(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated LatePctRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        rollups.track(sheet, by, () -> service.setLatePct(sheet, by, request.value()));
        return view(sheet);
    }

    /** Change the sheet's policy date; the figures it moves are followed in the audit. */
    @PutMapping("/policy-date")
    public SettingsView setPolicyDate(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated PolicyDateRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        rollups.track(sheet, by, () -> service.setPolicyDate(sheet, by, request.value()));
        return view(sheet);
    }

    /** Change the sheet's period numbering from; it numbers only claims opened from then on. */
    @PutMapping("/period-numbering-from")
    public SettingsView setPeriodNumberingFrom(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated PeriodNumberingFromRequest request) {
        String sheet = sheetId.trim();
        service.setPeriodNumberingFrom(sheet, SignedInUser.decode(user), request.value());
        return view(sheet);
    }

    private SettingsView view(String sheet) {
        BigDecimal limit = service.clerkLimit(sheet);
        LocalDate policyDate = service.policyDateSet(sheet);
        LocalDate numberingFrom = service.periodNumberingFrom(sheet);
        return new SettingsView(service.roles(sheet).stream().map(RoleView::of).toList(),
                limit != null ? limit.toPlainString() : null, service.floor(sheet).toPlainString(), service.terms(sheet),
                service.latePct(sheet).toPlainString(), policyDate != null ? policyDate.toString() : "",
                numberingFrom != null ? numberingFrom.toString() : "", service.gradeTerms(sheet));
    }

    /** A role that is not clerk or steward, or a limit that is not a number, is refused. */
    @ExceptionHandler({IllegalArgumentException.class, HttpMessageNotReadableException.class})
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }

    /** The user name's role was first set concurrently; caught by the unique index. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void conflict() {
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** A sheet's settings: the role each user name has on it, and its clerk limit, its floor, its terms
 *  (and any grade's own terms) and its late percent, its policy date and its period numbering from. */
@Service
public class SettingService {

    private final SheetService sheets;
    private final SheetRepository sheetRepository;
    private final SheetRoleRepository roles;
    private final GradeTermsRepository gradeTerms;
    private final Audit audit;

    public SettingService(SheetService sheets, SheetRepository sheetRepository, SheetRoleRepository roles,
            GradeTermsRepository gradeTerms, Audit audit) {
        this.sheets = sheets;
        this.sheetRepository = sheetRepository;
        this.roles = roles;
        this.gradeTerms = gradeTerms;
        this.audit = audit;
    }

    /** The roles assigned on the sheet, by user name. */
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserAsc(sheetId);
    }

    /** The user's role on the sheet: clerk unless assigned another. */
    public Role roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** The sheet's clerk limit; null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        return sheets.load(sheetId).getClerkLimit();
    }

    /** The sheet's floor: the least a claim's live due can be. */
    public BigDecimal floor(String sheetId) {
        return sheets.load(sheetId).getFloor();
    }

    /** The sheet's terms in days: a claim is due by its date plus them. */
    public int terms(String sheetId) {
        return sheets.load(sheetId).getTerms();
    }

    /** The grades' own terms on the sheet, by grade; a grade not listed takes the sheet's terms. */
    public Map<String, Integer> gradeTerms(String sheetId) {
        Map<String, Integer> byGrade = new LinkedHashMap<>();
        gradeTerms.findBySheetIdOrderByGradeAsc(sheetId).forEach(t -> byGrade.put(t.getGrade(), t.getTerms()));
        return byGrade;
    }

    /** The terms in days a claim of the grade takes now: the grade's own, else the sheet's. */
    public int termsFor(String sheetId, String grade) {
        if (grade == null) {
            return terms(sheetId);
        }
        return gradeTerms.findBySheetIdAndGrade(sheetId, grade).map(GradeTerms::getTerms)
                .orElseGet(() -> terms(sheetId));
    }

    /** The sheet's late percent: an overdue claim's due gains it of its figure for every full 30 days
     *  it is overdue. */
    public BigDecimal latePct(String sheetId) {
        return sheets.load(sheetId).getLatePct();
    }

    /** The sheet's policy date as set; null when it is blank (the sheet's today applies). */
    public LocalDate policyDateSet(String sheetId) {
        return sheets.load(sheetId).getPolicyDate();
    }

    /** The sheet's policy date in force: as set, else the sheet's today. */
    public LocalDate policyDate(String sheetId) {
        LocalDate set = policyDateSet(sheetId);
        return set != null ? set : sheets.today(sheetId);
    }

    /** The sheet's period numbering from; null when it is blank (off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        return sheets.load(sheetId).getPeriodNumberingFrom();
    }

    /** How a claim dated on the given date rounds: half up before the policy date, half to even on or
     *  after it. */
    public RoundingMode roundingOn(String sheetId, LocalDate date) {
        return date.isBefore(policyDate(sheetId)) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** Assign a user name a role on the sheet. */
    @Transactional
    public SheetRole setRole(String sheetId, String by, String user, Role role) {
        sheets.lock(sheetId);
