    this.clerkLimitTyped.set(false);
    this.floorTyped.set(false);
    this.termsTyped.set(false);
    this.gradeTerms.set({});
    this.latePctTyped.set(false);
    this.policyDateTyped.set(false);
    this.periodNumberingFromTyped.set(false);
