          inputmode="decimal"
          [value]="clerkLimit()"
          (focus)="clerkLimitTyped.set(true)"
          (input)="clerkLimit.set(value($event)); clerkLimitTyped.set(true); settingsError.set(null)"
        />
        <label for="setting-floor">Floor</label>
        <input
          id="setting-floor"
          data-testid="setting-floor"
          inputmode="decimal"
          [value]="floor()"
